import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.D7EuCHIT.js";const k=JSON.parse('{"title":"样式与绘制教程","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/styles.md","filePath":"plugins/styles.md","lastUpdated":1791713482000}'),n={name:"plugins/styles.md"};function l(r,e,p,d,o,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="样式与绘制教程" tabindex="-1">样式与绘制教程 <a class="header-anchor" href="#样式与绘制教程" aria-label="Permalink to &quot;样式与绘制教程&quot;">​</a></h1><p>使用 <code>examples/style.c</code>。插件在 query_interface 发布 <code>LyraStylesInterfaceV2</code>，count 返回描述数，describe 填写 <code>LyraStyleDescriptionV2</code>。</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LyraStylesInterfaceV2 styles </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(styles), LYRA_INTERFACE_VERSION, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, count, describe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>一个不同 id 添加一种样式；相同 id 可替换内置描述。使用稳定、带命名空间的 id，例如 <code>example.third</code>，不要每次版本更新更名。</p><h2 id="默认背景或整卡片绘制" tabindex="-1">默认背景或整卡片绘制 <a class="header-anchor" href="#默认背景或整卡片绘制" aria-label="Permalink to &quot;默认背景或整卡片绘制&quot;">​</a></h2><p><code>background_variant</code> 选择已有背景变体。非 NULL paint 回调替换整张播放卡片呈现，收到样式选择器计算的 x/y/w/h；通过 submit 画在同一坐标。它不是自动在默认歌词上加一个效果。需要歌词、控件、播放信息时自己查询公开接口并绘制。</p><p>input 处理该样式的输入；返回 0 让未消费事件继续进入默认导航。选择器打开期间输入由选择器处理，不自行绕过选择器命中。</p><h2 id="scene-协议" tabindex="-1">Scene 协议 <a class="header-anchor" href="#scene-协议" aria-label="Permalink to &quot;Scene 协议&quot;">​</a></h2><p>基础命令包括实色、封面、图标、短雾、流动背景、glyph、RGBA image。扩展文字层提供 tracking、词间距、方向、对齐、裁剪、模糊、扫光、变换中心与缩放；形状层提供渐变与边缘材质。具体字段以<a href="/LyraPlayer-docs-site/reference/abi">SDK</a>为准。</p><p>颜色为浮点 RGBA，几何为当前传入的像素坐标；dp 通过 density 换算，sp 还需字体缩放策略。不要混用 normalized ripple 中心与像素位置。</p><p>图标图集只含上一首、播放、暂停、下一首，不含启动三叶 Logo。封面 key 与资料库标志不能随意混用；插件应查询目录和有效图像语义而不是猜编码。</p><h2 id="文字和字体" tabindex="-1">文字和字体 <a class="header-anchor" href="#文字和字体" aria-label="Permalink to &quot;文字和字体&quot;">​</a></h2><p>glyph/text layer 接受 UTF-8 text 和 font。当前 Android 后端支持系统字体族名，绝对路径字体由 Typeface.createFromFile 读取，失败回退 sans-serif。字体文件必须在应用可访问路径；自定义 <code>.ttf/.otf</code> 不因为放 ZIP 里就自动切换全站字体。</p><p>默认字号由 <code>[player]</code> 等表控制；当前没有承诺一个默认全局 font 配置键。完整字体选择 UI 或默认全局字体功能需要新增配置及消费路径，或由自定义 UI 插件实现。不要发明不存在的 <code>font.family</code> 键。</p><h2 id="生命周期验收" tabindex="-1">生命周期验收 <a class="header-anchor" href="#生命周期验收" aria-label="Permalink to &quot;生命周期验收&quot;">​</a></h2><p>验证选择、缩放、切歌、暂停、横竖窗口变化、输入消费、卸载与缺失接口回退。不要在每个稳定帧分配新大数组；声明被宿主复制不意味着 paint 持有图像可以立即释放。</p><p>下一步：<a href="/LyraPlayer-docs-site/plugins/config-schema">可配置插件</a>。</p>`,17)])])}const y=a(n,[["render",l]]);export{k as __pageData,y as default};
